{
  "gate_token": "vRWIYB_L47ZUQV0e0gZ9aw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map at the broken city gate.",
      "visual_description": "A torn map spread over cracked cobblestones beneath a leaning gate arch, ink-stained fingers tracing a route as broken banners flap overhead.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of an obvious trap.",
      "visual_description": "An oil lamp held aloft in a misty alley, its single eye-flame pointing away from a too-inviting castle gate strung with golden chains.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the rubble-strewn plaza.",
      "visual_description": "A small clockwork fox darts between toppled statues, its key-wind tail ticking, blue glass eyes catching torchlight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver arrives through a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerges headfirst from a tall cracked window, coat rippling with reflected neon-bright city ruins.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They pass a snoring official slumped on the steps.",
      "visual_description": "A man asleep on the palace steps with a ledger as a pillow, stamped papers stuck to his sleeves, drool pooling on official seals.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle Lamp recoils from a cursed tower's pull.",
      "visual_description": "A spiraling black tower glowing violet from within; the lamp's flame bends backward as if afraid, sparks flying.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara charts a side route past armored patrols.",
      "visual_description": "From a rooftop, Mara sketches dotted lines on her map while distant helmeted silhouettes march in torchlit formation below.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a winged beast rumble overhead.",
      "visual_description": "An enormous shadow rolls across cracked rooftops; the diver crouches behind a chimney as scales-of-smoke drift past the moon.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox squeezes under a magic door.",
      "visual_description": "A glowing rune-etched door with a thin gap of light at its base, the clockwork fox flattening itself to slip beneath.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The Glass Diver swims through a mirrored hall.",
      "visual_description": "A long gallery of cracked mirrors with the diver suspended mid-stroke inside one pane, coat trailing like seaweed.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Oracle Lamp reveals the captive in a frozen chamber.",
      "visual_description": "Lamp-light spills across an iced-over throne room where the sleeping tax collector is propped against a pillar, snoring softly.",
      "characters": ["oracle_lamp", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "Mara realizes the official IS the rescue target.",
      "visual_description": "Mara's face lit from below by the lamp, her compass spinning wildly as she stares at the drooling, stamp-covered sleeper.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "They haul the snoring official through faded banners.",
      "visual_description": "The diver and Mara drag the limp tax collector by his ankles down a corridor of tattered royal banners, papers fluttering off him.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox triggers a decoy at the castle gates.",
      "visual_description": "The clockwork fox leaps onto a brazier, scattering sparks; armored shapes in the distance turn toward the false alarm.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Oracle Lamp points the way to the river bridge.",
      "visual_description": "The lamp's flame-eye stretches into an arrow shape, lighting a narrow alley that opens onto a fog-wreathed stone bridge.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "A roar shakes loose tiles as they sprint.",
      "visual_description": "Tiles cascade from rooftops as the team runs; the diver's helmet reflects a vast scaled silhouette uncoiling above the skyline.",
      "characters": ["glass_diver", "mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the cracking bridge.",
      "visual_description": "Stones split behind their heels on a long arched bridge over black water, lamp swinging wildly, fox skittering ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, the official sleeps on.",
      "visual_description": "Dawn light over a misty riverbank; Mara catches her breath, the diver removes the helmet's clasp, and the tax collector still snores on the grass beside the ticking fox.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

